async function handler(input) {
  const { order_id, refund_id, refund_amount, refund_note, client_id, client_secret, env } = input;
  const endpoint = (env === 'PRODUCTION')
    ? `https://api.cashfree.com/pg/orders/${order_id}/refunds`
    : `https://sandbox.cashfree.com/pg/orders/${order_id}/refunds`;

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-version': '2023-08-01',
      'x-client-id': client_id,
      'x-client-secret': client_secret
    },
    body: JSON.stringify({
      refund_id,
      refund_amount,
      refund_note: refund_note || 'Customer requested refund'
    })
  });

  const data = await response.json();
  if (!response.ok) {
    throw new Error(data.message || 'Refund initiation failed');
  }
  return data;
}
